const MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
const nowISO=()=>new Date().toISOString(),todayISO=()=>nowISO().slice(0,10),monthKey=d=>(d||new Date()).toISOString().slice(0,7);
function addMonths(key,n){let[y,m]=key.split('-').map(Number);m+=n;y+=Math.floor((m-1)/12);m=((m-1)%12+12)%12+1;return y+'-'+String(m).padStart(2,'0');}
function dueDateFor(month,day){const[y,m]=month.split('-').map(Number);const last=new Date(y,m,0).getDate();return month+'-'+String(Math.min(Math.max(day||5,1),last)).padStart(2,'0');}
function monthLabel(key){const[y,m]=key.split('-').map(Number);return MONTHS[m-1]+' '+y;}
function paisa(v){if(v==null||v==='')return 0;const n=Math.round(parseFloat(String(v).replace(/,/g,''))*100);return Number.isFinite(n)?n:0;}
function money(p,sym){sym=sym||S().currency;const n=(p||0)/100;return sym+' '+n.toLocaleString('en-US',{minimumFractionDigits:n%1?2:0,maximumFractionDigits:2});}
function fmtDate(iso,format){if(!iso)return '—';format=format||S().date_format;const[y,m,d]=iso.slice(0,10).split('-').map(Number);if(format==='d/m/Y')return String(d).padStart(2,'0')+'/'+String(m).padStart(2,'0')+'/'+y;if(format==='m/d/Y')return String(m).padStart(2,'0')+'/'+String(d).padStart(2,'0')+'/'+y;return d+' '+MONTHS[m-1].slice(0,3)+' '+y;}
const fmtDT=(iso,f)=>iso?fmtDate(iso,f)+' '+iso.slice(11,16):'—';
let _scache=null,_stime=0;
function S(){if(_scache&&Date.now()-_stime<2000)return _scache;const o={};for(const r of db.prepare('SELECT key,value FROM settings').all())o[r.key]=r.value;_scache=o;_stime=Date.now();return o;}
function setS(k,v){db.prepare('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').run(k,String(v));_scache=null;}
