function audit(user,action,detail){const prev=db.prepare('SELECT hash FROM audit ORDER BY id DESC LIMIT 1').get();const prevHash=prev?prev.hash:'GENESIS';const created=nowISO();const payload=prevHash+'|'+(user?user.id:0)+'|'+action+'|'+(detail||'')+'|'+created;const hash=crypto.createHash('sha256').update(payload).digest('hex');db.prepare('INSERT INTO audit(prev_hash,hash,user_id,action,detail,created_at) VALUES(?,?,?,?,?,?)').run(prevHash,hash,user?user.id:null,action,detail||'',created);}
function verifyAudit(){let prev='GENESIS';const rows=db.prepare('SELECT * FROM audit ORDER BY id').all();for(const r of rows){const payload=r.prev_hash+'|'+(r.user_id||0)+'|'+r.action+'|'+(r.detail||'')+'|'+r.created_at;const h=crypto.createHash('sha256').update(payload).digest('hex');if(r.prev_hash!==prev||r.hash!==h)return{ok:false,brokenAt:r.id};prev=r.hash;}return{ok:true,count:rows.length};}
function log(user,action,detail,link,propertyId){db.prepare('INSERT INTO activity(user_id,action,detail,link,property_id,created_at) VALUES(?,?,?,?,?,?)').run(user?user.id:null,action,detail||'',link||'',propertyId||null,nowISO());audit(user,action,detail);}
