function csvSend(res,name,headers,rows){const q=v=>'"'+String(v==null?'':v).replace(/"/g,'""')+'"';const body=[headers.map(q).join(','),...rows.map(r=>r.map(q).join(','))].join('\r\n');res.setHeader('Content-Type','text/csv; charset=utf-8');res.setHeader('Content-Disposition','attachment; filename="'+name+'.csv"');res.send('\uFEFF'+body);}
