const permSet=uid=>new Set(db.prepare('SELECT key FROM perms WHERE user_id=?').all(uid).map(r=>r.key));
function can(user,key){if(!user)return false;if(user.role==='admin')return true;if(user.fired)return false;if(!user._perms)user._perms=permSet(user.id);return user._perms.has(key);}
function propIds(user){if(!user||user.role==='admin'||can(user,'properties.viewAll'))return null;if(!can(user,'properties.viewAssigned'))return[];const a=db.prepare('SELECT property_id FROM employee_properties WHERE user_id=?').all(user.id).map(r=>r.property_id);const b=db.prepare('SELECT s.property_id FROM employee_spaces es JOIN spaces s ON s.id=es.space_id WHERE es.user_id=?').all(user.id).map(r=>r.property_id);return[...new Set([...a,...b])];}
function spaceIds(user){if(!user||user.role==='admin'||can(user,'properties.viewAll'))return null;const props=propIds(user);const a=props.length?db.prepare('SELECT id FROM spaces WHERE property_id IN ('+props.map(()=>'?').join(',')+')').all(...props).map(r=>r.id):[];const b=db.prepare('SELECT space_id FROM employee_spaces WHERE user_id=?').all(user.id).map(r=>r.space_id);return[...new Set([...a,...b])];}
function inClause(ids,col){if(ids===null)return{sql:'1=1',params:[]};if(!ids.length)return{sql:'0=1',params:[]};return{sql:col+' IN ('+ids.map(()=>'?').join(',')+')',params:ids};}
const propWhere=(u,col)=>inClause(propIds(u),col||'property_id');
const spaceWhere=(u,col)=>inClause(spaceIds(u),col||'space_id');
const canProp=(u,pid)=>{const ids=propIds(u);return ids===null||ids.includes(pid);};
const canSpace=(u,space)=>{const ids=spaceIds(u);return ids===null||ids.includes(space.id);};
function performance(uid){const today=todayISO();const tasks=db.prepare('SELECT * FROM tasks WHERE assigned_to=?').all(uid);const total=tasks.length;const completed=tasks.filter(t=>t.status==='Completed').length;const overdue=tasks.filter(t=>t.status!=='Completed'&&t.status!=='Cancelled'&&t.due_date&&t.due_date<today).length;const onTime=tasks.filter(t=>t.status==='Completed'&&t.completed_at&&(!t.due_date||t.completed_at.slice(0,10)<=t.due_date)).length;const payments=db.prepare('SELECT COUNT(*) c FROM payments WHERE added_by=? AND voided=0').get(uid).c;const sales=db.prepare('SELECT COUNT(*) c FROM sales WHERE employee_id=?').get(uid).c;let score=50;if(total){score+=Math.round(30*onTime/total);score-=Math.round(40*overdue/total);}score+=Math.min(15,payments*2);score+=Math.min(15,sales*3);score=Math.max(0,Math.min(100,score));let suggestion='ok';if(overdue>=2||(total>=3&&completed/total<0.4))suggestion='action';else if(score>=80&&onTime>=2)suggestion='raise';return{score,total,completed,overdue,onTime,payments,sales,suggestion};}
function attentionList(){const period=monthKey();const acks=new Set(db.prepare('SELECT user_id,kind FROM attention_ack WHERE period=?').all(period).map(r=>r.user_id+':'+r.kind));const out=[];for(const u of db.prepare("SELECT * FROM users WHERE role='employee' AND fired=0 AND active=1").all()){const p=performance(u.id);if(p.suggestion==='ok')continue;if(acks.has(u.id+':'+p.suggestion))continue;out.push({u,p});}return out;}
const WEEK=7*24*3600*1000,attempts=new Map();
function createSession(userId,returnTo){const token=crypto.randomBytes(32).toString('hex'),csrf=crypto.randomBytes(24).toString('hex');db.prepare('INSERT INTO sessions(token,user_id,csrf,return_to,created_at,expires_at) VALUES(?,?,?,?,?,?)').run(token,userId,csrf,returnTo||'',nowISO(),new Date(Date.now()+WEEK).toISOString());return{token,csrf};}
function setCookie(res,token){res.cookie('sid',token,{httpOnly:true,sameSite:'Lax',maxAge:WEEK,secure:process.env.SECURE_COOKIES==='1'});}
function destroySession(req,res){if(req.cookies.sid)db.prepare('DELETE FROM sessions WHERE token=?').run(req.cookies.sid);res.clearCookie('sid');}
function attach(req,res,next){req.user=null;req.session=null;const t=req.cookies.sid;if(t){const s=db.prepare('SELECT * FROM sessions WHERE token=? AND expires_at>?').get(t,nowISO());if(s){if(s.user_id){const u=db.prepare('SELECT * FROM users WHERE id=? AND active=1').get(s.user_id);if(u){req.user=u;req.session=s;}else{db.prepare('DELETE FROM sessions WHERE token=?').run(t);res.clearCookie('sid');}}else req.session=s;}}next();}
function csrfCheck(req,res,next){if(req.method!=='POST')return next();if(!req.session||!req.body._csrf||req.body._csrf!==req.session.csrf)return res.status(403).send(layout(req,'Not allowed',errBox('E-1004','This form was out of date. Please go back, refresh the page, and try again.')));next();}
function requireLogin(req,res,next){if(req.user)return next();if(req.method==='GET'){let s=req.session;if(!s){const n=createSession(null);setCookie(res,n.token);s=db.prepare('SELECT * FROM sessions WHERE token=?').get(n.token);}db.prepare('UPDATE sessions SET return_to=? WHERE token=?').run(req.originalUrl,s.token);return res.redirect('/login');}res.status(401).send('Please sign in first.');}
function requireAdmin(req,res,next){if(req.user&&req.user.role==='admin'&&!req.user.fired)return next();res.status(403).send(layout(req,'Not allowed',errBox('E-1003','Only the Administrator can open this page.')));}
const requirePerm=key=>(req,res,next)=>can(req.user,key)?next():res.status(403).send(layout(req,'Not allowed',errBox('E-1003','You do not have access to this page. Ask your manager if you need it.')));
function firedLockdown(req,res,next){if(req.user&&req.user.fired){const ok=['/fired','/fired/message','/logout','/style.css','/app.js','/logo'];if(!ok.includes(req.path))return res.redirect('/fired');}next();}
function ensureRecords(){const upto=monthKey();const ins=db.prepare('INSERT OR IGNORE INTO rent_records(tenancy_id,month,amount,due_date) VALUES(?,?,?,?)');const touched=new Set();const rows=db.prepare('SELECT * FROM tenancies').all();db.transaction(()=>{for(const t of rows){let mk=t.move_in.slice(0,7);const end=t.move_out?t.move_out.slice(0,7):upto;let guard=0;while(mk<=end&&mk<=upto&&guard++<120){const r=ins.run(t.id,mk,t.rent,dueDateFor(mk,t.due_day));if(r.changes)touched.add(t.id);mk=addMonths(mk,1);}}})();for(const id of touched)reallocateTenancy(id);}
function reallocateTenancy(tid){db.transaction(()=>{const records=db.prepare('SELECT * FROM rent_records WHERE tenancy_id=? ORDER BY month').all(tid);const pays=db.prepare("SELECT * FROM payments WHERE kind='rent' AND tenancy_id=? AND voided=0 ORDER BY paid_on,id").all(tid);db.prepare("DELETE FROM payment_allocations WHERE record_kind='rent' AND payment_id IN (SELECT id FROM payments WHERE kind='rent' AND tenancy_id=?)").run(tid);const paid={};const ins=db.prepare("INSERT INTO payment_allocations(payment_id,record_kind,record_id,amount) VALUES(?,'rent',?,?)");for(const p of pays){let left=p.amount;for(const r of records){if(left<=0)break;const open=r.amount-(paid[r.id]||0);if(open<=0)continue;const take=Math.min(left,open);ins.run(p.id,r.id,take);paid[r.id]=(paid[r.id]||0)+take;left-=take;}}})();}
function reallocateSale(sid){db.transaction(()=>{const plan=db.prepare('SELECT * FROM plans WHERE sale_id=?').get(sid);db.prepare("DELETE FROM payment_allocations WHERE record_kind='installment' AND payment_id IN (SELECT id FROM payments WHERE kind='sale' AND sale_id=?)").run(sid);if(!plan)return;const insts=db.prepare('SELECT * FROM installments WHERE plan_id=? ORDER BY n').all(plan.id);const pays=db.prepare("SELECT * FROM payments WHERE kind='sale' AND sale_id=? AND voided=0 AND is_initial=0 ORDER BY paid_on,id").all(sid);const paid={};const ins=db.prepare("INSERT INTO payment_allocations(payment_id,record_kind,record_id,amount) VALUES(?,'installment',?,?)");for(const p of pays){let left=p.amount;for(const r of insts){if(left<=0)break;const open=r.amount-(paid[r.id]||0);if(open<=0)continue;const take=Math.min(left,open);ins.run(p.id,r.id,take);paid[r.id]=(paid[r.id]||0)+take;left-=take;}}})();}
function paidMap(kind){const o={};for(const r of db.prepare("SELECT a.record_id id,SUM(a.amount) paid FROM payment_allocations a JOIN payments p ON p.id=a.payment_id WHERE p.voided=0 AND a.record_kind=? GROUP BY a.record_id").all(kind))o[r.id]=r.paid;return o;}
const recordStatus=(a,p,d,t)=>p>=a?'Paid':d<t?'Late':p>0?'Partly Paid':'Unpaid';
const instStatus=(a,p,d,t)=>p>=a?'Paid':d<t?'Late':p>0?'Partly Paid':d===t?'Due':'Upcoming';
function tenancySummary(tid){const due=db.prepare('SELECT COALESCE(SUM(amount),0) v FROM rent_records WHERE tenancy_id=?').get(tid).v;const paid=db.prepare("SELECT COALESCE(SUM(amount),0) v FROM payments WHERE kind='rent' AND tenancy_id=? AND voided=0").get(tid).v;const alloc=db.prepare("SELECT COALESCE(SUM(a.amount),0) v FROM payment_allocations a JOIN payments p ON p.id=a.payment_id WHERE p.voided=0 AND p.kind='rent' AND p.tenancy_id=? AND a.record_kind='rent'").get(tid).v;const pm=paidMap('rent');const recs=db.prepare('SELECT * FROM rent_records WHERE tenancy_id=? ORDER BY month').all(tid);const today=todayISO();const open=recs.filter(r=>(pm[r.id]||0)<r.amount);const last=db.prepare("SELECT MAX(paid_on) v FROM payments WHERE kind='rent' AND tenancy_id=? AND voided=0").get(tid).v;const remaining=Math.max(due-alloc,0);const anyLate=open.some(r=>r.due_date<today);const status=due===0?'Unpaid':remaining===0?'Paid':anyLate?'Late':alloc>0?'Partly Paid':'Unpaid';return{due,paid,allocated:alloc,remaining,advance:paid-alloc,nextDue:open.length?open[0].due_date:'',lastPayment:last||'',status,records:recs,paidByRecord:pm};}
function saleSummary(sid){const sale=db.prepare('SELECT * FROM sales WHERE id=?').get(sid);const paid=db.prepare("SELECT COALESCE(SUM(amount),0) v FROM payments WHERE kind='sale' AND sale_id=? AND voided=0").get(sid).v;const plan=db.prepare('SELECT * FROM plans WHERE sale_id=?').get(sid);let installments=[];if(plan){const pm=paidMap('installment');const today=todayISO();installments=db.prepare('SELECT * FROM installments WHERE plan_id=? ORDER BY n').all(plan.id).map(i=>({...i,paid:pm[i.id]||0,remaining:i.amount-(pm[i.id]||0),status:instStatus(i.amount,pm[i.id]||0,i.due_date,today)}));}return{sale,paid,remaining:Math.max(sale.agreed_price-paid,0),plan,installments};}
const activeTenancy=sid=>db.prepare('SELECT * FROM tenancies WHERE space_id=? AND move_out IS NULL ORDER BY id DESC LIMIT 1').get(sid);
const tenancyInfo=id=>db.prepare("SELECT t.*,tn.name tenant_name,tn.phone tenant_phone,tn.whatsapp tenant_whatsapp,s.name space_name,s.floor,s.property_id,p.name property_name FROM tenancies t JOIN tenants tn ON tn.id=t.tenant_id JOIN spaces s ON s.id=t.space_id JOIN properties p ON p.id=s.property_id WHERE t.id=?").get(id);
function checkDue(){ensureRecords();const s=S();const today=todayISO();const admins=db.prepare("SELECT id FROM users WHERE role='admin' AND active=1").all().map(r=>r.id);if(s.notify_rent==='1'){const soon=new Date(Date.now()+(parseInt(s.rent_remind_days,10)||3)*86400000).toISOString().slice(0,10);const pm=paidMap('rent');const rows=db.prepare("SELECT r.*,s.name space_name,p.name property_name,tn.name tenant_name FROM rent_records r JOIN tenancies t ON t.id=r.tenancy_id JOIN spaces s ON s.id=t.space_id JOIN properties p ON p.id=s.property_id JOIN tenants tn ON tn.id=t.tenant_id WHERE r.due_date<=?").all(soon);for(const r of rows){if((pm[r.id]||0)>=r.amount)continue;const late=r.due_date<today;const msg=(late?'Rent is late: ':'Rent due soon: ')+r.space_name+' ('+r.property_name+') — '+r.tenant_name+', due '+fmtDate(r.due_date);for(const uid of admins)notify(uid,msg,'/rent?tab='+(late?'late':'upcoming'),(late?'rentlate':'rentdue')+':'+r.id);}}if(s.notify_tasks==='1'){const soon=new Date(Date.now()+(parseInt(s.task_remind_days,10)||2)*86400000).toISOString().slice(0,10);const rows=db.prepare("SELECT * FROM tasks WHERE status IN ('Not Started','In Progress') AND due_date<>'' AND due_date<=?").all(soon);for(const t of rows){const late=t.due_date<today;const msg=(late?'Task is late: ':'Task due soon: ')+t.title+' (due '+fmtDate(t.due_date)+')';const key='task:'+t.id+':'+(late?'late':'soon');if(t.assigned_to)notify(t.assigned_to,msg,'/tasks/'+t.id,key);for(const uid of admins)notify(uid,msg,'/tasks/'+t.id,key);}}}
const CHIP_COLORS={'Paid':'green','Rented':'blue','Completed':'green','Confirmed':'green','Deal Completed':'green','Active':'green','Yes':'green','Late':'red','Urgent':'red','Cancelled':'red','Turned off':'red','Fired':'red','Unpaid':'gray','Partly Paid':'amber','Reserved':'amber','In Progress':'blue','Interested':'blue','High':'amber','Empty':'gray','Closed':'gray','Moved out':'gray','New':'blue','Contacted':'blue','Property Shown':'blue','Not Interested':'gray','Looking':'blue','Bought':'green','Due':'amber','Upcoming':'gray','Not Started':'gray','Low':'gray','Normal':'gray','Working':'green','None':'gray'};
const chip=t=>'<span class="chip '+(CHIP_COLORS[t]||'')+'">'+esc(t==null||t===''?'—':t)+'</span>';
const btn=(href,label,cls)=>'<a class="btn '+(cls||'')+'" href="'+href+'">'+esc(label)+'</a>';
function toastHtml(req){if(!req.flash)return '';const f=req.flash;const isErr=f.type==='err';const title=isErr?('Error '+(f.code||'E-1000')):'Success';return '<div class="toast-wrap" id="toastWrap"><div class="toast '+(isErr?'toast-err':'toast-ok')+'" role="alert"><div class="toast-icon">'+(isErr?'&#10007;':'&#10003;')+'</div><div class="toast-body"><strong>'+esc(title)+'</strong><span>'+esc(f.msg)+'</span></div><button class="toast-x" onclick="this.parentNode.parentNode.remove()" aria-label="Close">&times;</button></div></div>';}
function errBox(code,msg){return '<div class="error-page"><div class="error-code">'+esc(code||'E-1000')+'</div><h1>Sorry</h1><p>'+esc(msg)+'</p><p>'+btn('/','Go to the dashboard')+'</p></div>';}
function attentionHtml(req){const u=req.user;if(!u||u.role!=='admin'||u.fired)return '';const list=attentionList();if(!list.length)return '';
 let h='<div class="attn"><div class="attn-head">&#9888; Staff attention needed — choose an action for each person</div>';
 for(const{u:e,p}of list){const raise=p.suggestion==='raise';const back=esc(req.path);
  const msg=raise?('is doing great (score '+p.score+'/100, '+p.onTime+' tasks on time). Consider a salary raise.'):(p.overdue+' overdue task'+(p.overdue===1?'':'s')+', score '+p.score+'/100. Performance is poor — act now.');
  h+='<div class="attn-item '+(raise?'attn-good':'attn-bad')+'"><div class="attn-msg"><strong>'+esc(e.name)+'</strong> <span class="muted">('+esc(e.job_role||'Staff')+')</span> '+esc(msg)+'</div><div class="attn-actions">';
  h+='<form method="post" action="/staff/'+e.id+'/ack" class="inline"><input type="hidden" name="_csrf" value="'+req.csrf+'"><input type="hidden" name="back" value="'+back+'"><input type="hidden" name="kind" value="'+p.suggestion+'"><button class="btn small">Do nothing</button></form>';
  if(raise){h+='<form method="post" action="/staff/'+e.id+'/raise" class="inline attn-form"><input type="hidden" name="_csrf" value="'+req.csrf+'"><input type="hidden" name="back" value="'+back+'"><input type="text" inputmode="decimal" name="amount" placeholder="Raise amount" required><input type="text" name="reason" placeholder="Why (optional)"><button class="btn small primary">Give raise</button></form>';}
  else{h+='<form method="post" action="/staff/'+e.id+'/warn" class="inline attn-form"><input type="hidden" name="_csrf" value="'+req.csrf+'"><input type="hidden" name="back" value="'+back+'"><input type="text" name="message" placeholder="Warning message (optional)"><button class="btn small">Warn</button></form>';
   h+='<form method="post" action="/staff/'+e.id+'/deduct" class="inline attn-form" data-confirm="Deduct salary and issue an urgent warning?"><input type="hidden" name="_csrf" value="'+req.csrf+'"><input type="hidden" name="back" value="'+back+'"><input type="text" inputmode="decimal" name="amount" placeholder="Deduct amount" required><input type="text" name="reason" placeholder="Why (optional)"><button class="btn small danger">Deduct + warn</button></form>';
   h+='<form method="post" action="/staff/'+e.id+'/fire" class="inline attn-form" data-confirm="Fire this employee? They lose all access immediately."><input type="hidden" name="_csrf" value="'+req.csrf+'"><input type="hidden" name="back" value="'+back+'"><input type="text" name="reason" placeholder="Reason (optional)"><button class="btn small danger">Fire</button></form>';}
  h+='</div></div>';}
 return h+'</div>';}
function navHtml(req){const u=req.user,p=req.path;const on=x=>p===x||p.startsWith(x+'/')?' class="on"':'';let n='<a href="/"'+(p==='/'?' class="on"':'')+'>Dashboard</a>';const has=(...k)=>k.some(x=>can(u,x));
 if(has('properties.viewAll','properties.viewAssigned')){n+='<div class="nav-group">Properties</div><a href="/properties"'+on('/properties')+'>'+(u.role==='employee'?'My Properties':'Properties')+'</a><a href="/properties?type=Building">Buildings</a>';}
 if(can(u,'spaces.view'))n+='<a href="/spaces"'+on('/spaces')+'>Rooms & Flats</a>';
 if(has('tenants.view','customers.view','seekers.view','employees.view')){n+='<div class="nav-group">People</div>';if(can(u,'tenants.view'))n+='<a href="/tenants"'+on('/tenants')+'>Tenants</a>';if(can(u,'customers.view'))n+='<a href="/customers"'+on('/customers')+'>Customers</a>';if(can(u,'seekers.view'))n+='<a href="/seekers"'+on('/seekers')+'>People Looking for Property</a>';if(can(u,'employees.view'))n+='<a href="/employees"'+on('/employees')+'>Employees</a>';}
 if(has('rent.view','payments.viewHistory','sales.view','expenses.view')){n+='<div class="nav-group">Money</div>';if(can(u,'rent.view'))n+='<a href="/rent"'+on('/rent')+'>Rent</a>';if(can(u,'payments.viewHistory'))n+='<a href="/payments"'+on('/payments')+'>Payments</a>';if(can(u,'sales.view')){n+='<a href="/sales"'+on('/sales')+'>Sales</a><a href="/plans"'+on('/plans')+'>Payment Plans</a>';}if(can(u,'expenses.view'))n+='<a href="/expenses"'+on('/expenses')+'>Expenses</a>';}
 n+='<div class="nav-group">Work</div>';if(can(u,'tasks.view'))n+='<a href="/tasks"'+on('/tasks')+'>Tasks</a>';if(can(u,'qr.scan'))n+='<a href="/scan"'+on('/scan')+'>Scan QR</a>';if(u.role==='admin')n+='<a href="/qr"'+on('/qr')+'>QR Codes</a>';if(can(u,'documents.view'))n+='<a href="/documents"'+on('/documents')+'>Documents</a>';if(can(u,'reports.view'))n+='<a href="/reports"'+on('/reports')+'>Reports</a>';
 n+='<a href="/activity"'+on('/activity')+'>Recent Activity</a>';const unread=db.prepare('SELECT COUNT(*) c FROM notifications WHERE user_id=? AND read=0').get(u.id).c;n+='<a href="/notifications"'+on('/notifications')+'>Notifications'+(unread?' <span class="badge">'+unread+'</span>':'')+'</a>';if(can(u,'messages.send'))n+='<a href="/messages"'+on('/messages')+'>Send a Message</a>';
 if(u.role==='admin'){n+='<div class="nav-group">System</div><a href="/integrity"'+on('/integrity')+'>Anti-Theft Check</a><a href="/settings"'+on('/settings')+'>Settings</a>';}
 n+='<a href="/profile"'+on('/profile')+'>My Profile</a><form method="post" action="/logout" class="logout-form"><input type="hidden" name="_csrf" value="'+req.csrf+'"><button class="linklike">Logout</button></form>';return n;}
function layout(req,title,body){const u=req.user,s=S();const head='<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf" content="'+(req.csrf||'')+'"><title>'+esc(title?title+' — ':'')+esc(s.company_name)+'</title><link rel="stylesheet" href="/style.css"></head><body>';
 if(!u||u.fired)return head+'<div class="plain">'+toastHtml(req)+body+'</div><script src="/app.js"></script></body></html>';
 return head+'<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand">'+(s.logo_path?'<img src="/logo" alt="">':'')+'<span>'+esc(s.company_name)+'</span></div><nav>'+navHtml(req)+'</nav></aside><div class="main"><header class="topbar"><button class="menu-btn" id="menuBtn" aria-label="Menu">&#9776;</button><form method="get" action="/search" class="topsearch"><input type="search" name="q" placeholder="Search properties, rooms, tenants, phone numbers, receipts…"></form><a class="topname" href="/profile">'+esc(u.name)+'<small>'+(u.role==='admin'?'Administrator':esc(u.job_role||'Staff'))+'</small></a></header><main class="content">'+attentionHtml(req)+toastHtml(req)+body+'</main></div></div><script src="/app.js"></script></body></html>';}
const send=(res,req,title,body)=>res.send(layout(req,title,body));
function pageHead(title,actions){return '<div class="page-head"><h1>'+esc(title)+'</h1><div>'+(actions||'')+'</div></div>';}
function tableHtml(headers,rows){let h='<div class="table-wrap"><table class="table"><tr>'+headers.map(x=>'<th'+(x.num?' class="num"':'')+'>'+esc(x.label||x)+'</th>').join('')+'</tr>';if(!rows.length)h+='<tr><td colspan="'+headers.length+'" class="muted">Nothing here yet.</td></tr>';for(const r of rows)h+='<tr>'+r.map(c=>'<td'+(c&&c.num?' class="num"':'')+'>'+(c&&c.html!=null?c.html:esc(c&&c.text!=null?c.text:c))+'</td>').join('')+'</tr>';return h+'</table></div>';}
const num=v=>({html:esc(v),num:true});const link=(href,text)=>({html:'<a href="'+href+'">'+esc(text)+'</a>'});
function pagerHtml(page,pages,qs){if(pages<=1)return '';let h='<div class="pager">';for(let i=1;i<=pages;i++)h+=i===page?'<span class="pg on">'+i+'</span>':'<a class="pg" href="?'+qs+'&page='+i+'">'+i+'</a>';return h+'</div>';}
function docsBlock(req,lt,lid,docs){const u=req.user;let h='<div class="card"><div class="card-head"><h3>Documents</h3></div>';if(docs&&docs.length){h+='<table class="table"><tr><th>Name</th><th>Kind</th><th>Date</th><th></th></tr>';for(const d of docs){h+='<tr><td>'+esc(d.title)+'</td><td>'+esc(d.category)+'</td><td>'+fmtDate(d.created_at)+'</td><td class="actions">'+btn('/documents/'+d.id+'/file','View','small')+' '+btn('/documents/'+d.id+'/file?download=1','Download','small')+(can(u,'documents.delete')?' <form method="post" action="/documents/'+d.id+'/delete" class="inline" data-confirm="Remove this document?"><input type="hidden" name="_csrf" value="'+req.csrf+'"><input type="hidden" name="back" value="'+esc(req.path)+'"><button class="btn small danger">Remove</button></form>':'')+'</td></tr>';}h+='</table>';}else h+='<p class="muted">No documents yet.</p>';
 if(can(u,'documents.upload')){h+='<form method="post" action="/documents" enctype="multipart/form-data" class="rowform"><input type="hidden" name="_csrf" value="'+req.csrf+'"><input type="hidden" name="linked_type" value="'+lt+'"><input type="hidden" name="linked_id" value="'+lid+'"><input type="hidden" name="back" value="'+esc(req.path)+'"><input type="text" name="title" placeholder="Document name" required><select name="category">'+['Photo','Rental agreement','Sale agreement','Payment receipt','Property papers','Tenant document','Customer document','Employee document','Other'].map(c=>'<option>'+c+'</option>').join('')+'</select><input type="file" name="file" required><button class="btn">Upload</button></form>';}return h+'</div>';}
const sel=a=>a.map(v=>({v,l:v}));const fromList=k=>u=>sel(listOf(S(),k));
