const relSpaces=u=>{const w=spaceWhere(u,'s.id');return db.prepare("SELECT s.id,s.name||' — '||p.name l FROM spaces s JOIN properties p ON p.id=s.property_id WHERE "+w.sql+" ORDER BY p.name,s.name").all(...w.params).map(r=>({v:r.id,l:r.l}));};
