function fieldHtml(f,value,req){const v=value==null?'':value;const star=f.required?' <span class="req">*</span>':'';const common='id="f_'+f.key+'" name="'+f.key+'"';let input;
 if(f.type==='textarea')input='<textarea '+common+' rows="3">'+esc(v)+'</textarea>';
 else if(f.type==='select'){const opts=typeof f.opts==='function'?f.opts(req.user):(f.opts||[]);input='<select '+common+'><option value="">— choose —</option>'+opts.map(o=>'<option value="'+esc(o.v)+'"'+(String(v)===String(o.v)?' selected':'')+'>'+esc(o.l)+'</option>').join('')+'</select>';}
 else if(f.type==='money')input='<input '+common+' type="text" inputmode="decimal" value="'+(v===''?'':esc(typeof v==='number'?v/100:v))+'" placeholder="e.g. 25000">';
 else if(f.type==='file')input='<input '+common+' type="file" accept=".pdf,.jpg,.jpeg,.png,.webp,.gif,.doc,.docx,.xls,.xlsx,.txt,.csv">';
 else{const t={number:'number',date:'date',email:'email',tel:'tel'}[f.type]||'text';input='<input '+common+' type="'+t+'" value="'+esc(v)+'">';}
 return '<div class="field'+(f.type==='textarea'?' wide':'')+'"><label for="f_'+f.key+'">'+esc(f.label)+star+'</label>'+input+'</div>';}
function formPage(req,res,title,action,fields,values,submitLabel,cancelHref,multipart){const body=pageHead(title,'')+'<div class="card form-card"><form method="post" action="'+action+'"'+(multipart?' enctype="multipart/form-data"':'')+'><input type="hidden" name="_csrf" value="'+req.csrf+'"><div class="form-grid">'+fields.map(f=>fieldHtml(f,values[f.key],req)).join('')+'</div><div class="form-actions"><button class="btn primary big">'+esc(submitLabel)+'</button> '+btn(cancelHref,'Cancel')+'</div></form></div>';send(res,req,title,body);}
