function spaceView(req,res,space,printMode){ensureRecords();const t=activeTenancy(space.id);const tenancy=t?tenancyInfo(t.id):null;const summary=t?tenancySummary(t.id):null;
 const pays=t&&can(req.user,'payments.viewHistory')?db.prepare("SELECT p.*,u.name aname FROM payments p LEFT JOIN users u ON u.id=p.added_by WHERE p.kind='rent' AND p.tenancy_id=? ORDER BY p.paid_on DESC,p.id DESC").all(t.id):[];
 const qr=db.prepare('SELECT * FROM qr_codes WHERE space_id=? AND active=1 ORDER BY id DESC LIMIT 1').get(space.id);
 const docs=db.prepare("SELECT * FROM documents WHERE linked_type='space' AND linked_id=?").all(space.id);
 const showContact=can(req.user,'tenants.viewContact'),showRent=can(req.user,'rent.view'),showRemaining=can(req.user,'rent.viewRemaining');
 let info='<dl class="dl"><dt>Property</dt><dd>'+esc(space.property_name)+'</dd><dt>Floor</dt><dd>'+space.floor+'</dd><dt>Type</dt><dd>'+esc(space.type)+'</dd>'+(showRent?'<dt>Monthly rent</dt><dd>'+money(space.rent)+'</dd><dt>Security deposit</dt><dd>'+money(space.deposit)+'</dd>':'')+'<dt>Rent due day</dt><dd>Day '+space.due_day+' of each month</dd></dl>'+(space.notes?'<p class="note"><strong>Notes:</strong> '+esc(space.notes)+'</p>':'');
 if(tenancy){info+='<hr><h3>Tenant</h3><p><strong><a href="/tenants/'+tenancy.tenant_id+'">'+esc(tenancy.tenant_name)+'</a></strong><br>'+(showContact?'<a href="tel:'+esc(tenancy.tenant_phone)+'">'+esc(tenancy.tenant_phone)+'</a><br>':'')+'<span class="muted">Moved in '+fmtDate(tenancy.move_in)+'</span></p>';
  if(summary&&(showRent||showRemaining)){info+='<table class="table">'+(showRent?'<tr><td>Total rent due</td><td class="num">'+money(summary.due)+'</td></tr><tr><td>Total paid</td><td class="num">'+money(summary.paid)+'</td></tr>':'')+(showRemaining?'<tr><td><strong>Remaining amount</strong></td><td class="num"><strong>'+money(summary.remaining)+'</strong></td></tr>'+(summary.advance>0?'<tr><td>Extra paid (advance)</td><td class="num">'+money(summary.advance)+'</td></tr>':''):'')+(summary.nextDue?'<tr><td>Next rent due</td><td>'+fmtDate(summary.nextDue)+'</td></tr>':'')+(summary.lastPayment?'<tr><td>Last payment</td><td>'+fmtDate(summary.lastPayment)+'</td></tr>':'')+'<tr><td>Status</td><td>'+chip(summary.status)+'</td></tr></table>';}
  info+='<div class="rowform">'+(can(req.user,'payments.add')?btn('/payments/new?tenancy='+tenancy.id,'Add payment','primary big'):'')+(can(req.user,'tenants.moveOut')?'<form method="post" action="/tenancies/'+tenancy.id+'/move-out" class="inline" data-confirm="Mark this tenant as moved out? All history is kept."><input type="hidden" name="_csrf" value="'+req.csrf+'"><input type="date" name="move_out"><button class="btn">Mark as moved out</button></form>':'')+'</div>';}
 else{info+='<hr><p class="muted">Nobody is living here right now.</p>';
  if(can(req.user,'tenants.add')&&space.status!=='Closed'){const topts=db.prepare("SELECT id,name||' — '||phone l FROM tenants ORDER BY name").all();
   info+='<h3>Move in a tenant</h3><form method="post" action="/spaces/'+space.id+'/move-in" class="form-grid"><input type="hidden" name="_csrf" value="'+req.csrf+'"><div class="field"><label>Choose an existing tenant</label><select name="tenant_id"><option value="">— new tenant below —</option>'+topts.map(t=>'<option value="'+t.id+'">'+esc(t.l)+'</option>').join('')+'</select></div><div class="field"><label>Or new tenant\u2019s name</label><input type="text" name="new_name"></div><div class="field"><label>New tenant\u2019s phone</label><input type="tel" name="new_phone"></div><div class="field"><label>Monthly rent</label><input type="text" inputmode="decimal" name="rent" value="'+(space.rent/100)+'"></div><div class="field"><label>Security deposit</label><input type="text" inputmode="decimal" name="deposit" value="'+(space.deposit/100)+'"></div><div class="field"><label>Rent due day (1–28)</label><input type="number" name="due_day" min="1" max="28" value="'+space.due_day+'"></div><div class="field"><label>Move-in date</label><input type="date" name="move_in"></div><div class="form-actions wide"><button class="btn primary">Move in</button></div></form>';}}
 let qrBlock='';if(req.user.role==='admin'||qr){qrBlock='<div class="card"><div class="card-head"><h3>QR code</h3></div>'+(qr?'<p class="muted">A working QR code exists for this room.</p>'+(req.user.role==='admin'?'<div class="rowform">'+btn('/qr/'+qr.id+'/png','Download')+' '+btn('/qr/print?ids='+qr.id,'Print')+' <form method="post" action="/qr/'+qr.id+'/replace" class="inline" data-confirm="Replace? The old printed code stops working."><input type="hidden" name="_csrf" value="'+req.csrf+'"><button class="btn">Replace</button></form> <form method="post" action="/qr/'+qr.id+'/toggle" class="inline"><input type="hidden" name="_csrf" value="'+req.csrf+'"><button class="btn danger">Turn off</button></form></div>':''):'<p class="muted">No QR code yet.</p>'+(req.user.role==='admin'?'<form method="post" action="/qr/create"><input type="hidden" name="_csrf" value="'+req.csrf+'"><input type="hidden" name="space_id" value="'+space.id+'"><button class="btn primary">Create QR code</button></form>':''))+'</div>';}
 let hist='';if(can(req.user,'payments.viewHistory')&&pays.length){hist='<div class="card"><div class="card-head"><h3>Payment history</h3></div>'+tableHtml(['Date',{label:'Amount',num:true},'Method','Receipt','Added by'],pays.map(p=>[fmtDate(p.paid_on),num(money(p.amount)),p.method,{html:'<a href="/payments/'+p.id+'">'+esc(p.receipt_no)+'</a>'+(p.voided?' '+chip('Cancelled'):'')},p.aname]))+'</div>';}
 if(printMode){const body='<div class="print-sheet"><h1>'+esc(S().company_name)+'</h1><h2>'+esc(space.property_name)+' — '+esc(space.name)+'</h2>'+info+'<p class="muted">Printed '+fmtDate(nowISO())+'</p><button class="btn primary no-print" onclick="window.print()">Print</button></div>';return res.send('<!DOCTYPE html><html><head><meta charset="utf-8"><title>'+esc(space.name)+'</title><link rel="stylesheet" href="/style.css"></head><body class="print-body">'+body+'</body></html>');}
 const actions=btn('/properties/'+space.property_id,space.property_name)+(can(req.user,'properties.edit')?' '+btn('/spaces/'+space.id+'/edit','Change'):'')+' '+btn('/spaces/'+space.id+'/print','Print details');
 const body=pageHead(space.name+' '+chip(space.status),actions)+'<div class="grid-2"><div class="card">'+info+'</div><div>'+qrBlock+hist+'</div></div>'+docsBlock(req,'space',space.id,docs);
 send(res,req,space.name,body);}
