 const moveIn=/^\d{4}-\d{2}-\d{2}$/.test(req.body.move_in||'')?req.body.move_in:todayISO();const rent=paisa(req.body.rent)||space.rent;const deposit=paisa(req.body.deposit||0)||space.deposit;const dueDay=clampInt(req.body.due_day,1,28,space.due_day||5);
 if(rent<=0){flash(res,'Please write the monthly rent.','err','E-1006');return res.redirect('/spaces/'+space.id);}
