 let left='<dl class="dl"><dt>Amount</dt><dd><strong>'+money(p.amount)+'</strong></dd><dt>Date</dt><dd>'+fmtDate(p.paid_on)+'</dd><dt>Method</dt><dd>'+esc(p.method)+'</dd><dt>For</dt><dd>'+(p.kind==='rent'?'Rent':'Property sale')+'</dd>'+(p.kind==='rent'?'<dt>Tenant</dt><dd><a href="/tenants/'+p.tenant_id+'">'+esc(p.tenant_name)+'</a></dd><dt>Room</dt><dd><a href="/spaces/'+p.space_id+'">'+esc(p.space_name)+'</a> · '+esc(p.property_name)+'</dd>':'<dt>Buyer</dt><dd><a href="/sales/'+p.sale_id+'">'+esc(p.buyer_name)+'</a> · '+esc(p.sale_property_name)+'</dd>')+'<dt>Added by</dt><dd>'+esc(p.aname)+'</dd><dt>Saved on</dt><dd>'+fmtDT(p.created_at)+'</dd><dt>Verification code</dt><dd><strong>'+esc(p.verify_code||verifyCode(p))+'</strong> · <a href="/verify?receipt_no='+esc(p.receipt_no)+'&code='+esc(p.verify_code||verifyCode(p))+'">Verify</a></dd>'+(showRemaining&&summary?'<dt>Remaining amount now</dt><dd><strong>'+money(summary.remaining)+'</strong></dd>':'')+(p.notes?'<dt>Notes</dt><dd>'+esc(p.notes)+'</dd>':'')+(p.voided?'<dt>Cancelled because</dt><dd>'+esc(p.void_reason)+'</dd>':'')+'</dl>';
 let right='';if(canEdit&&!p.voided){right='<div class="card"><div class="card-head"><h3>Correct this payment</h3></div><p class="muted small-text">The old values are kept on record. Nothing is erased.</p><form method="post" action="/payments/'+p.id+'" class="form-grid"><input type="hidden" name="_csrf" value="'+req.csrf+'"><div class="field"><label>Correct amount</label><input type="text" inputmode="decimal" name="amount" value="'+(p.amount/100)+'"></div><div class="field"><label>Correct date</label><input type="date" name="paid_on" value="'+p.paid_on+'"></div><div class="field"><label>Method</label><select name="method">'+listOf(S(),'payment_methods').map(m=>'<option'+(p.method===m?' selected':'')+'>'+m+'</option>').join('')+'</select></div><div class="field wide"><label>Why is this being changed? <span class="req">*</span></label><input type="text" name="reason" required></div><div class="field wide"><label>Notes</label><textarea name="notes" rows="2">'+esc(p.notes)+'</textarea></div><div class="form-actions wide"><button class="btn primary">Save correction</button></div></form><hr><form method="post" action="/payments/'+p.id+'/void" data-confirm="Cancel this payment? It stays in the history, marked as cancelled."><input type="hidden" name="_csrf" value="'+req.csrf+'"><div class="field"><label>Cancel this payment — why?</label><input type="text" name="reason" required></div><button class="btn danger">Cancel this payment</button></form>'+(edits.length?'<hr><h3>Changes made to this payment</h3>'+tableHtml(['When','Who','Before','Why'],edits.map(e=>{const o=JSON.parse(e.old_values);return[fmtDT(e.changed_at),e.ename,money(o.amount)+' · '+fmtDate(o.paid_on)+' · '+o.method,e.reason];})):'')+'</div>';}
 const body=pageHead('Receipt '+p.receipt_no+(p.voided?' '+chip('Cancelled'):''),btn('/payments/'+p.id+'/receipt','Print receipt','primary'))+'<div class="grid-2"><div class="card">'+left+'</div><div>'+right+'</div></div>';
