function docScopeOk(user,d){if(user.role==='admin')return true;if(!can(user,'documents.view'))return false;const one=(sql,...p)=>db.prepare(sql).get(...p);
 switch(d.linked_type){case 'property':return canProp(user,d.linked_id);
  case 'space':{const s=one('SELECT * FROM spaces WHERE id=?',d.linked_id);return s&&canSpace(user,s);}
  case 'tenant':{const ids=spaceIds(user);if(ids===null)return true;return !!one('SELECT id FROM tenancies WHERE tenant_id=? AND space_id IN ('+(ids.map(()=>'?').join(',')||'NULL')+') LIMIT 1',d.linked_id,...ids);}
  case 'customer':{const c=one('SELECT * FROM customers WHERE id=?',d.linked_id);return c&&RES.customers.canSee(user,c);}
  case 'sale':{const s=one('SELECT * FROM sales WHERE id=?',d.linked_id);return s&&RES.sales.canSee(user,s);}
  case 'employee':return d.linked_id===user.id;
  case 'payment':{const p=one('SELECT * FROM payments WHERE id=?',d.linked_id);if(!p)return false;if(p.added_by===user.id)return true;if(p.kind==='rent'){const t=one('SELECT * FROM tenancies WHERE id=?',p.tenancy_id);const s=t&&one('SELECT * FROM spaces WHERE id=?',t.space_id);return s&&canSpace(user,s);}return canProp(user,(one('SELECT property_id FROM sales WHERE id=?',p.sale_id)||{}).property_id);}
  default:return false;}}
app.get('/documents',requireLogin,requirePerm('documents.view'),(req,res)=>{let rows=db.prepare('SELECT d.*,u.name uname FROM documents d LEFT JOIN users u ON u.id=d.uploaded_by ORDER BY d.id DESC LIMIT 300').all().filter(d=>docScopeOk(req.user,d));
 const q=String(req.query.q||'').toLowerCase();if(q)rows=rows.filter(d=>(d.title+d.orig_name+d.category).toLowerCase().includes(q));
 const labels={};for(const d of rows){const key=d.linked_type+':'+d.linked_id;if(!(key in labels)){const t={property:'properties',space:'spaces',tenant:'tenants',customer:'customers',sale:'sales',employee:'users'}[d.linked_type];const r=t?db.prepare('SELECT name FROM '+t+' WHERE id=?').get(d.linked_id):null;labels[key]=r?r.name:(d.linked_type==='payment'?'Payment':'—');}d._linked=d.linked_type?labels[key]+' ('+d.linked_type+')':'—';}
 const body=pageHead('Documents',can(req.user,'documents.upload')?btn('/documents/new','Upload a document','primary'):'')+'<form method="get" class="filterbar"><input type="search" name="q" placeholder="Search documents…" value="'+esc(req.query.q||'')+'"><button class="btn">Search</button></form><div class="card">'+tableHtml(['Document','Kind','Connected to','Uploaded by','Date',''],rows.map(d=>[link('/documents/'+d.id+'/file',d.title),d.category,d._linked,d.uname,fmtDate(d.created_at),{html:btn('/documents/'+d.id+'/file','View','small')+' '+btn('/documents/'+d.id+'/file?download=1','Download','small')}]))+'</div>';
 send(res,req,'Documents',body);});
