 if(!f||!title){flash(res,'Please choose a file and write a name for it.','err','E-1006');return res.redirect(req.body.back||'/documents/new');}
 const lt=String(req.body.linked_type||'');const lid=parseInt(req.body.linked_id,10)||0;
 if(lt&&req.user.role!=='admin'&&!docScopeOk(req.user,{linked_type:lt,linked_id:lid})){removeFile(f.filename);return errSend(res,req,403,'You cannot attach files to that record.');}
 createDoc(f,{title,category:req.body.category,linked_type:lt,linked_id:lid,user:req.user});flash(res,'Document uploaded.');
 const back=req.body.back||(({property:'/properties/',space:'/spaces/',tenant:'/tenants/',customer:'/customers/',sale:'/sales/',employee:'/employees/'}[lt]||'')+lid)||'/documents';
