const REPORTS=[['rent_received','Rent received'],['rent_unpaid','Rent still unpaid'],['rent_late','Late rent'],['rent_upcoming','Upcoming rent dates'],['rent_monthly','Monthly rent totals'],['payments_range','Payments between dates'],['payments_property','Payments by property'],['payments_employee','Payments by employee'],['payments_method','Payments by method'],['properties','All properties and spaces'],['sales','Sales'],['expenses','Expenses'],['expenses_type','Expenses by type'],['expenses_month','Expenses by month'],['employees','Work done by employees']];
app.get('/reports',requireLogin,requirePerm('reports.view'),(req,res)=>{ensureRecords();const type=REPORTS.some(r=>r[0]===req.query.type)?req.query.type:'rent_received';const from=req.query.from||monthKey()+'-01';const to=req.query.to||todayISO();const s=S(),u=req.user,today=todayISO();const pw=propWhere(u,'s.property_id');const pm=paidMap('rent');let headers=[],rows=[],totals=null;const M=v=>money(v);
 const rentRows=()=>db.prepare('SELECT r.*,tn.name tenant_name,s.name space_name,p.name property_name FROM rent_records r JOIN tenancies t ON t.id=r.tenancy_id JOIN tenants tn ON tn.id=t.tenant_id JOIN spaces s ON s.id=t.space_id JOIN properties p ON p.id=s.property_id WHERE '+pw.sql).all(...pw.params).map(r=>({...r,paid:pm[r.id]||0,remaining:r.amount-(pm[r.id]||0),status:recordStatus(r.amount,pm[r.id]||0,r.due_date,today)}));
 const payRows=()=>db.prepare("SELECT p.*,u.name aname,tn.name tenant_name,sl.buyer_name,COALESCE(sp.name,slp.name) property_name,s.name space_name FROM payments p LEFT JOIN users u ON u.id=p.added_by LEFT JOIN tenancies t ON t.id=p.tenancy_id LEFT JOIN tenants tn ON tn.id=t.tenant_id LEFT JOIN spaces s ON s.id=t.space_id LEFT JOIN properties sp ON sp.id=s.property_id LEFT JOIN sales sl ON sl.id=p.sale_id LEFT JOIN properties slp ON slp.id=sl.property_id WHERE p.voided=0 AND p.paid_on BETWEEN ? AND ? ORDER BY p.paid_on").all(from,to).filter(p=>u.role==='admin'||p.added_by===u.id);
 if(type==='rent_received'){const rr=payRows().filter(p=>p.kind==='rent');headers=['Date','Receipt','Tenant','Property','Room','Method','Added by','Amount'];rows=rr.map(p=>[fmtDate(p.paid_on),p.receipt_no,p.tenant_name,p.property_name,p.space_name,p.method,p.aname,M(p.amount)]);totals=['Total','','','','','','',M(rr.reduce((a,p)=>a+p.amount,0))];}
 else if(['rent_unpaid','rent_late','rent_upcoming'].includes(type)){let rr=rentRows().filter(r=>r.remaining>0);if(type==='rent_late')rr=rr.filter(r=>r.due_date<today);if(type==='rent_upcoming')rr=rr.filter(r=>r.due_date>=today).sort((a,b)=>a.due_date.localeCompare(b.due_date));headers=['Due date','Month','Tenant','Property','Room','Rent','Paid','Remaining amount','Status'];rows=rr.map(r=>[fmtDate(r.due_date),monthLabel(r.month),r.tenant_name,r.property_name,r.space_name,M(r.amount),M(r.paid),M(r.remaining),r.status]);totals=['Total','','','','',M(rr.reduce((a,r)=>a+r.amount,0)),M(rr.reduce((a,r)=>a+r.paid,0)),M(rr.reduce((a,r)=>a+r.remaining,0)),''];}
 else if(type==='rent_monthly'){const map={};for(const r of rentRows()){map[r.month]=map[r.month]||{due:0,paid:0};map[r.month].due+=r.amount;map[r.month].paid+=r.paid;}headers=['Month','Rent due','Rent paid','Remaining amount'];rows=Object.keys(map).sort().reverse().map(k=>[monthLabel(k),M(map[k].due),M(map[k].paid),M(map[k].due-map[k].paid)]);}
 else if(type==='payments_range'){const rr=payRows();headers=['Date','Receipt','Rent / sale','Tenant / buyer','Property','Method','Added by','Amount'];rows=rr.map(p=>[fmtDate(p.paid_on),p.receipt_no,p.kind==='rent'?'Rent':'Sale',p.tenant_name||p.buyer_name,p.property_name,p.method,p.aname,M(p.amount)]);totals=['Total','','','','','','',M(rr.reduce((a,p)=>a+p.amount,0))];}
 else if(['payments_property','payments_employee','payments_method'].includes(type)){const key=type==='payments_property'?'property_name':type==='payments_employee'?'aname':'method';const map={};for(const p of payRows()){const k=p[key]||'—';map[k]=map[k]||{n:0,sum:0};map[k].n++;map[k].sum+=p.amount;}headers=[type==='payments_property'?'Property':type==='payments_employee'?'Employee':'Method','Number of payments','Total'];rows=Object.entries(map).sort((a,b)=>b[1].sum-a[1].sum).map(([k,v])=>[k,v.n,M(v.sum)]);totals=['Total',Object.values(map).reduce((a,v)=>a+v.n,0),M(Object.values(map).reduce((a,v)=>a+v.sum,0))];}
 else if(type==='properties'){headers=['Property','Type','City','Owner','Spaces','Rented','Empty','Reserved','Closed'];const props=db.prepare('SELECT * FROM properties WHERE '+propWhere(u,'id').sql+' ORDER BY name').all(...propWhere(u,'id').params);rows=props.map(p=>{const c={Rented:0,Empty:0,Reserved:0,Closed:0};const sp=db.prepare('SELECT status FROM spaces WHERE property_id=?').all(p.id);sp.forEach(x=>c[x.status]++);return[p.name,p.type,p.city,p.owner_name,sp.length,c.Rented,c.Empty,c.Reserved,c.Closed];});}
 else if(type==='sales'){headers=['Buyer','Property','Status','Agreed price','Amount paid','Remaining amount','Sale date'];const sales=db.prepare('SELECT * FROM sales ORDER BY id DESC').all().filter(x=>RES.sales.canSee(u,x));let tp=0,tpd=0;rows=sales.map(x=>{const sm=saleSummary(x.id);tp+=x.agreed_price;tpd+=sm.paid;return[x.buyer_name,(db.prepare('SELECT name FROM properties WHERE id=?').get(x.property_id)||{}).name,x.status,M(x.agreed_price),M(sm.paid),M(sm.remaining),fmtDate(x.sale_date)];});totals=['Total','','',M(tp),M(tpd),M(tp-tpd),''];}
 else if(['expenses','expenses_type','expenses_month'].includes(type)){const ex=db.prepare('SELECT e.*,p.name property_name FROM expenses e LEFT JOIN properties p ON p.id=e.property_id WHERE e.spent_on BETWEEN ? AND ? ORDER BY e.spent_on').all(from,to).filter(e=>RES.expenses.canSee(u,e));
  if(type==='expenses'){headers=['Date','Expense','Type','Property','Paid by','Method','Amount'];rows=ex.map(e=>[fmtDate(e.spent_on),e.name,e.type,e.property_name||'—',e.paid_by,e.method,M(e.amount)]);}
  else{const map={};for(const e of ex){const k=type==='expenses_type'?e.type:e.spent_on.slice(0,7);map[k]=(map[k]||0)+e.amount;}headers=[type==='expenses_type'?'Type':'Month','Total'];rows=Object.entries(map).sort().map(([k,v])=>[type==='expenses_month'?monthLabel(k):k,M(v)]);}
  totals=type==='expenses'?['Total','','','','','',M(ex.reduce((a,e)=>a+e.amount,0))]:['Total',M(ex.reduce((a,e)=>a+e.amount,0))];}
 else if(type==='employees'){if(u.role!=='admin')return errSend(res,req,403,'Only the manager can see this report.');headers=['Employee','Role','Account','Work score','Assigned work','Work completed','Payments added','Sales handled'];rows=db.prepare("SELECT * FROM users WHERE role='employee' ORDER BY name").all().map(e=>{const c=sql=>db.prepare(sql).get(e.id).c;const pf=performance(e.id);return[e.name,e.job_role||'Staff',e.fired?'Fired':(e.active?'Active':'Turned off'),pf.score+'/100',c('SELECT COUNT(*) c FROM tasks WHERE assigned_to=?'),c("SELECT COUNT(*) c FROM tasks WHERE assigned_to=? AND status='Completed'"),c('SELECT COUNT(*) c FROM payments WHERE added_by=? AND voided=0'),c('SELECT COUNT(*) c FROM sales WHERE employee_id=?')];});}
 if(req.query.format==='csv')return csvSend(res,type,headers,rows);
 const body=pageHead('Reports','')+'<form method="get" class="filterbar"><select name="type" onchange="this.form.submit()">'+REPORTS.map(([k,l])=>'<option value="'+k+'"'+(type===k?' selected':'')+'>'+l+'</option>').join('')+'</select><label class="inline-label">From <input type="date" name="from" value="'+from+'"></label><label class="inline-label">To <input type="date" name="to" value="'+to+'"></label><button class="btn">Show</button> '+btn('?type='+type+'&from='+from+'&to='+to+'&format=csv','Download as Excel file (CSV)')+'</form><div class="card">'+tableHtml(headers,rows)+(totals?'<p><strong>'+totals.map(esc).join(' · ')+'</strong></p>':'')+'</div>';
 send(res,req,'Reports',body);});
