app.post('/settings/restore',requireLogin,requireAdmin,(req,res)=>{const f=(req.files||[]).find(x=>x.fieldname==='backup');if(!f){flash(res,'Please choose a backup file.','err','E-1006');return res.redirect('/settings');}
 try{const test=new Database(f.path,{readonly:true});const ok=test.prepare("SELECT name FROM sqlite_master WHERE name='users'").get();test.close();if(!ok)throw new Error('bad');
  db.close();fs.copyFileSync(path.join(DATA,'app.sqlite'),path.join(DATA,'before-restore.sqlite'));fs.copyFileSync(f.path,path.join(DATA,'app.sqlite'));
  flash(res,'Backup restored. The app will restart — refresh the page in a moment.');res.redirect('/login');setTimeout(()=>process.exit(0),300);}
 catch(e){removeFile(f.filename);flash(res,'That file is not a backup made by this system. Nothing was changed.','err','E-1007');res.redirect('/settings');}});
function loadSample(){if(db.prepare('SELECT COUNT(*) c FROM properties WHERE is_sample=1').get().c)return;const now=nowISO(),today=todayISO();const monthAgo=addMonths(monthKey(),-1)+'-05';
 const prop=db.prepare("INSERT INTO properties(name,type,address,city,area,owner_name,owner_phone,is_sample,created_at) VALUES('Sample — ABC Building','Building','12 Main Road','Lahore','Johar Town','Sample Owner','0300-0000001',1,?)").run(now).lastInsertRowid;
 const prop2=db.prepare("INSERT INTO properties(name,type,city,area,owner_name,owner_phone,is_sample,created_at) VALUES('Sample — Green House','House','Lahore','Model Town','Sample Owner 2','0300-0000002',1,?)").run(now).lastInsertRowid;
 const sids=[];for(let i=1;i<=6;i++)sids.push(db.prepare("INSERT INTO spaces(property_id,name,floor,type,rent,deposit,due_day,status,is_sample,created_at) VALUES(?,?,?,?,?,?,?,?,1,?)").run(prop,'Room '+i,i<=3?1:2,'Room',2500000,5000000,5,'Empty',now).lastInsertRowid);
 const t1=db.prepare("INSERT INTO tenants(name,phone,whatsapp,is_sample,created_at) VALUES('Sample — Ahmed Khan','0300-1111111','0300-1111111',1,?)").run(now).lastInsertRowid;
 const t2=db.prepare("INSERT INTO tenants(name,phone,is_sample,created_at) VALUES('Sample — Sara Ali','0300-2222222',1,?)").run(now).lastInsertRowid;
 const ten1=db.prepare('INSERT INTO tenancies(tenant_id,space_id,rent,deposit,due_day,move_in,is_sample) VALUES(?,?,?,?,?,?,1)').run(t1,sids[0],2500000,5000000,5,monthAgo).lastInsertRowid;
 db.prepare('INSERT INTO tenancies(tenant_id,space_id,rent,deposit,due_day,move_in,is_sample) VALUES(?,?,?,?,?,?,1)').run(t2,sids[1],2500000,5000000,5,monthAgo);
 db.prepare("UPDATE spaces SET status='Rented' WHERE id IN (?,?)").run(sids[0],sids[1]);db.prepare("UPDATE spaces SET status='Reserved' WHERE id=?").run(sids[2]);
 const admin=db.prepare("SELECT id FROM users WHERE role='admin' LIMIT 1").get();
 const emp=db.prepare("INSERT INTO users(role,name,email,password_hash,phone,job_title,job_role,is_sample,created_at) VALUES('employee','Sample — Bilal','sample.employee@example.com',?,'0300-3333333','Field staff','Agent',1,?)").run(bcrypt.hashSync('sample12345',10),now).lastInsertRowid;
 for(const k of ROLE_PRESETS.Agent)db.prepare('INSERT OR IGNORE INTO perms(user_id,key) VALUES(?,?)').run(emp,k);
 db.prepare('INSERT INTO employee_properties(user_id,property_id) VALUES(?,?)').run(emp,prop);
 const cust=db.prepare("INSERT INTO customers(name,phone,city,budget,want,assigned_to,created_by,is_sample,created_at) VALUES('Sample — Usman Buyer','0300-4444444','Lahore',500000000,'Buy',?,?,1,?)").run(emp,admin.id,now).lastInsertRowid;
 db.prepare("INSERT INTO seekers(name,phone,looking_for,want,budget,preferred_area,status,assigned_to,created_by,is_sample,created_at) VALUES('Sample — Ayesha','0300-5555555','2-bedroom flat','Rent',3000000,'Johar Town','Property Shown',?,?,1,?)").run(emp,admin.id,now);
 const sale=db.prepare("INSERT INTO sales(buyer_name,customer_id,property_id,employee_id,list_price,agreed_price,commission,sale_date,status,is_sample,created_at) VALUES('Sample — Usman Buyer',?,?,?,?,?,?,?,'Confirmed',1,?)").run(cust,prop2,emp,1050000000,1000000000,20000000,today,now).lastInsertRowid;
 const planId=db.prepare('INSERT INTO plans(sale_id,total,initial,count,start_date,created_at) VALUES(?,?,?,?,?,?)').run(sale,1000000000,200000000,4,today,now).lastInsertRowid;
 for(let n=1;n<=4;n++)db.prepare('INSERT INTO installments(plan_id,n,amount,due_date) VALUES(?,?,?,?)').run(planId,n,200000000,dueDateFor(addMonths(monthKey(),n),5));
 db.prepare("INSERT INTO tasks(title,description,assigned_to,property_id,due_date,priority,created_by,is_sample,created_at) VALUES('Sample — Collect rent from Room 1','Visit and collect this month''s rent.',?,?,?,'High',?,1,?)").run(emp,prop,monthKey()+'-05',admin.id,now);
 db.prepare("INSERT INTO expenses(name,amount,type,spent_on,paid_by,method,property_id,added_by,is_sample,created_at) VALUES('Sample — Water tank repair',150000,'Repairs',?,'Cash office','Cash',?,?,1,?)").run(today,prop,admin.id,now);
 for(const sid of sids.slice(0,3))db.prepare('INSERT INTO qr_codes(space_id,token,created_at) VALUES(?,?,?)').run(sid,crypto.randomBytes(18).toString('hex'),now);
 ensureRecords();
 const pid=db.prepare("INSERT INTO payments(kind,tenancy_id,amount,paid_on,method,added_by,notes,is_sample,created_at) VALUES('rent',?,2000000,?,'Cash',?,'Sample partial payment',1,?)").run(ten1,monthKey()+'-03',admin.id,now).lastInsertRowid;
 db.prepare('UPDATE payments SET receipt_no=? WHERE id=?').run('RC-'+String(pid).padStart(5,'0'),pid);const pp=db.prepare('SELECT * FROM payments WHERE id=?').get(pid);db.prepare('UPDATE payments SET verify_code=? WHERE id=?').run(verifyCode(pp),pid);reallocateTenancy(ten1);
 const spid=db.prepare("INSERT INTO payments(kind,sale_id,amount,paid_on,method,added_by,notes,is_initial,is_sample,created_at) VALUES('sale',?,200000000,?,'Bank',?,'Sample first payment',1,1,?)").run(sale,today,admin.id,now).lastInsertRowid;
 db.prepare('UPDATE payments SET receipt_no=? WHERE id=?').run('SC-'+String(spid).padStart(5,'0'),spid);const sp=db.prepare('SELECT * FROM payments WHERE id=?').get(spid);db.prepare('UPDATE payments SET verify_code=? WHERE id=?').run(verifyCode(sp),spid);reallocateSale(sale);}
function removeSample(){db.transaction(()=>{db.prepare('DELETE FROM payment_allocations WHERE payment_id IN (SELECT id FROM payments WHERE is_sample=1)').run();db.prepare('DELETE FROM payment_edits WHERE payment_id IN (SELECT id FROM payments WHERE is_sample=1)').run();db.prepare('DELETE FROM payments WHERE is_sample=1').run();db.prepare('DELETE FROM rent_records WHERE tenancy_id IN (SELECT id FROM tenancies WHERE is_sample=1)').run();db.prepare('DELETE FROM installments WHERE plan_id IN (SELECT pl.id FROM plans pl JOIN sales s ON s.id=pl.sale_id WHERE s.is_sample=1)').run();db.prepare('DELETE FROM plans WHERE sale_id IN (SELECT id FROM sales WHERE is_sample=1)').run();db.prepare('DELETE FROM sales WHERE is_sample=1').run();db.prepare('DELETE FROM customer_visits WHERE customer_id IN (SELECT id FROM customers WHERE is_sample=1)').run();db.prepare('DELETE FROM tenancies WHERE is_sample=1').run();db.prepare('DELETE FROM tenants WHERE is_sample=1').run();db.prepare('DELETE FROM customers WHERE is_sample=1').run();db.prepare('DELETE FROM seekers WHERE is_sample=1').run();db.prepare('DELETE FROM tasks WHERE is_sample=1').run();db.prepare('DELETE FROM expenses WHERE is_sample=1').run();db.prepare('DELETE FROM qr_codes WHERE space_id IN (SELECT id FROM spaces WHERE is_sample=1)').run();db.prepare('DELETE FROM spaces WHERE is_sample=1').run();db.prepare('DELETE FROM properties WHERE is_sample=1').run();db.prepare('DELETE FROM users WHERE is_sample=1').run();db.prepare("DELETE FROM notifications WHERE message LIKE '%Sample —%'").run();})();}
app.post('/settings/sample',requireLogin,requireAdmin,(req,res)=>{if(req.body.action==='load'){loadSample();log(req.user,'Loaded sample data','','/settings');flash(res,'Sample data loaded. Every sample record is marked “Sample”.');}else{removeSample();log(req.user,'Removed sample data','','/settings');flash(res,'All sample data removed. Real records were not touched.');}res.redirect('/settings');});
app.get('/search',requireLogin,(req,res)=>{const q=String(req.query.q||'').trim();const groups=[];
 if(q.length>=2){const like='%'+q+'%';const pw=propWhere(req.user,'id');const add=(label,rows)=>rows.length&&groups.push({label,rows});
  add('Properties',db.prepare('SELECT id,name text,city sub FROM properties WHERE '+pw.sql+' AND (name LIKE ? OR city LIKE ? OR area LIKE ? OR owner_phone LIKE ?) LIMIT 8').all(...pw.params,like,like,like,like).map(r=>({...r,href:'/properties/'+r.id})));
  if(can(req.user,'spaces.view')){const sw=spaceWhere(req.user,'s.id');add('Rooms and flats',db.prepare('SELECT s.id,s.name text,p.name sub FROM spaces s JOIN properties p ON p.id=s.property_id WHERE '+sw.sql+' AND (s.name LIKE ? OR p.name LIKE ?) LIMIT 8').all(...sw.params,like,like).map(r=>({...r,href:'/spaces/'+r.id})));}
  if(can(req.user,'tenants.view')){const sw=spaceWhere(req.user,'t.space_id');add('Tenants',db.prepare('SELECT DISTINCT tn.id,tn.name text,tn.phone sub FROM tenants tn JOIN tenancies t ON t.tenant_id=tn.id WHERE '+sw.sql+' AND (tn.name LIKE ? OR tn.phone LIKE ? OR tn.whatsapp LIKE ?) LIMIT 8').all(...sw.params,like,like,like).map(r=>({...r,href:'/tenants/'+r.id,sub:can(req.user,'tenants.viewContact')?r.sub:''})));}
  if(can(req.user,'customers.view'))add('Customers',db.prepare('SELECT id,name text,phone sub FROM customers WHERE name LIKE ? OR phone LIKE ? LIMIT 8').all(like,like).map(r=>({...r,href:'/customers/'+r.id})));
  if(can(req.user,'seekers.view'))add('People looking for property',db.prepare('SELECT id,name text,phone sub FROM seekers WHERE name LIKE ? OR phone LIKE ? LIMIT 8').all(like,like).map(r=>({...r,href:'/seekers/'+r.id})));
  if(can(req.user,'employees.view'))add('Employees',db.prepare("SELECT id,name text,job_title sub FROM users WHERE role='employee' AND (name LIKE ? OR phone LIKE ? OR email LIKE ?) LIMIT 8").all(like,like,like).map(r=>({...r,href:'/employees/'+r.id})));
  if(can(req.user,'payments.viewHistory'))add('Payments (receipt number)',db.prepare('SELECT id,receipt_no text,paid_on sub FROM payments WHERE receipt_no LIKE ? LIMIT 8').all(like).map(r=>({...r,href:'/payments/'+r.id})));
  if(can(req.user,'sales.view'))add('Sales',db.prepare('SELECT id,buyer_name text,status sub FROM sales WHERE buyer_name LIKE ? LIMIT 8').all(like).map(r=>({...r,href:'/sales/'+r.id})));}
 const body=pageHead('Search','')+'<form method="get" class="filterbar"><input type="search" name="q" value="'+esc(q)+'" placeholder="Name, phone number, room, receipt number…" autofocus><button class="btn primary">Search</button></form>'+(q&&q.length<2?'<p class="muted">Type at least 2 letters.</p>':'')+groups.map(g=>'<div class="card"><div class="card-head"><h3>'+g.label+'</h3></div>'+tableHtml(['',''],g.rows.map(r=>[link(r.href,r.text),{html:'<span class="muted">'+esc(r.sub||'')+'</span>'}]))+'</div>').join('')+(q&&q.length>=2&&!groups.length?'<div class="card"><p class="muted">Nothing found for “'+esc(q)+'”. Try a different spelling, or a phone number.</p></div>':'');
 send(res,req,'Search',body);});
app.get('/notifications',requireLogin,(req,res)=>{const rows=db.prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 200').all(req.user.id);
 const body=pageHead('Notifications','<form method="post" action="/notifications/read-all"><input type="hidden" name="_csrf" value="'+req.csrf+'"><button class="btn">Mark all as read</button></form>')+'<div class="card">'+rows.map(n=>'<div class="notif-row '+(n.read?'':'unread')+'"><div>'+(n.link?'<a href="'+n.link+'">'+esc(n.message)+'</a>':esc(n.message))+'<small class="muted">'+fmtDT(n.created_at)+'</small></div>'+(n.read?'':'<form method="post" action="/notifications/'+n.id+'/read"><input type="hidden" name="_csrf" value="'+req.csrf+'"><button class="btn small">Mark as read</button></form>')+'</div>').join('')+(rows.length?'':'<p class="muted">No notifications.</p>')+'</div>';
 send(res,req,'Notifications',body);});
app.post('/notifications/:id(\\d+)/read',requireLogin,(req,res)=>{db.prepare('UPDATE notifications SET read=1 WHERE id=? AND user_id=?').run(req.params.id,req.user.id);res.redirect(req.body.back||'/notifications');});
app.post('/notifications/read-all',requireLogin,(req,res)=>{db.prepare('UPDATE notifications SET read=1 WHERE user_id=?').run(req.user.id);res.redirect('/notifications');});
app.get('/activity',requireLogin,(req,res)=>{const where=[];const params=[];if(req.user.role!=='admin'){const pw=propWhere(req.user,'property_id');where.push('(a.user_id=? OR ('+pw.sql+'))');params.push(req.user.id,...pw.params);}
 if(req.query.from){where.push('a.created_at>=?');params.push(req.query.from);}if(req.query.to){where.push('a.created_at<=?');params.push(req.query.to+'T23:59');}if(req.query.q){where.push('(a.action LIKE ? OR a.detail LIKE ?)');params.push('%'+req.query.q+'%','%'+req.query.q+'%');}
 const wsql=where.length?where.join(' AND '):'1=1';const rows=db.prepare('SELECT a.*,u.name uname FROM activity a LEFT JOIN users u ON u.id=a.user_id WHERE '+wsql+' ORDER BY a.id DESC LIMIT 300').all(...params);
 const body=pageHead('Recent Activity','')+'<form method="get" class="filterbar"><input type="search" name="q" placeholder="Search actions…" value="'+esc(req.query.q||'')+'"><label class="inline-label">From <input type="date" name="from" value="'+esc(req.query.from||'')+'"></label><label class="inline-label">To <input type="date" name="to" value="'+esc(req.query.to||'')+'"></label><button class="btn">Search</button></form><div class="card">'+tableHtml(['Who','What happened','Details','Date','Time'],rows.map(a=>[a.uname||'System',a.link?link(a.link,a.action):a.action,a.detail,fmtDate(a.created_at),a.created_at.slice(11,16)]))+'</div>';
 send(res,req,'Recent Activity',body);});
app.get('/messages',requireLogin,(req,res,next)=>{if(!can(req.user,'messages.send'))return next();const recipients=req.user.role==='admin'?db.prepare("SELECT id,name l FROM users WHERE role='employee' AND active=1 AND fired=0 ORDER BY name").all():db.prepare("SELECT id,name||' (Manager)' l FROM users WHERE role='admin' AND active=1").all();
 const body=pageHead('Send a Message','')+'<div class="card form-card"><form method="post" action="/messages" class="form-grid"><input type="hidden" name="_csrf" value="'+req.csrf+'"><div class="field"><label>Send to</label><select name="to" required><option value="">— choose —</option>'+recipients.map(r=>'<option value="'+r.id+'">'+esc(r.l)+'</option>').join('')+'</select></div><div class="field wide"><label>Message</label><textarea name="text" rows="3" required placeholder="Write your message…"></textarea></div><div class="form-actions wide"><button class="btn primary">Send</button></div></form><p class="muted small-text">The message appears in their Notifications inside the system.</p></div>';
 send(res,req,'Send a Message',body);});
app.post('/messages',requireLogin,(req,res)=>{if(!can(req.user,'messages.send'))return errSend(res,req,403,'You are not allowed to send messages.');const text=String(req.body.text||'').trim();const to=parseInt(req.body.to,10);
 if(!text||!to){flash(res,'Please choose a person and write a message.','err','E-1006');return res.redirect('/messages');}
 const target=db.prepare('SELECT * FROM users WHERE id=? AND active=1').get(to);const allowed=req.user.role==='admin'?target&&target.role==='employee':target&&target.role==='admin';
 if(!allowed)return errSend(res,req,403,'You cannot send a message to this person.');notify(to,'Message from '+req.user.name+': '+text,'/notifications');log(req.user,'Sent a message','To '+target.name,'/notifications');flash(res,'Message sent.');res.redirect('/messages');});
app.get('/integrity',requireLogin,requireAdmin,(req,res)=>{const v=verifyAudit();
 const body=pageHead('Anti-Theft Check','')+'<div class="card">'+(v.ok?'<p class="verify-ok">&#10003; The record chain is intact. '+v.count+' entries verified. No tampering detected.</p>':'<p class="verify-bad">&#10007; Tampering detected at entry '+v.brokenAt+'. A past record was changed or removed.</p>')+'<p class="muted">Every action is locked into a tamper-proof chain. If anyone alters or deletes a past record, this check fails.</p>'+btn('/verify','Open the public receipt verifier')+'</div>';
 send(res,req,'Anti-Theft Check',body);});
app.get('/verify',(req,res)=>{const rn=String(req.query.receipt_no||'').trim();const code=String(req.query.code||'').trim().toUpperCase();let result='';
 if(rn&&code){const p=db.prepare("SELECT p.*,tn.name tenant_name,s.name space_name,sp.name property_name,sl.buyer_name,slp.name sale_property_name FROM payments p LEFT JOIN tenancies t ON t.id=p.tenancy_id LEFT JOIN tenants tn ON tn.id=t.tenant_id LEFT JOIN spaces s ON s.id=t.space_id LEFT JOIN properties sp ON sp.id=s.property_id LEFT JOIN sales sl ON sl.id=p.sale_id LEFT JOIN properties slp ON slp.id=sl.property_id WHERE p.receipt_no=?").get(rn);
  if(p&&verifyCode(p)===code){result='<div class="card verify-ok"><h3>&#10003; Genuine receipt</h3><table class="table"><tr><td>Receipt</td><td>'+esc(p.receipt_no)+'</td></tr><tr><td>Amount</td><td><strong>'+money(p.amount)+'</strong></td></tr><tr><td>Date</td><td>'+fmtDate(p.paid_on)+'</td></tr><tr><td>For</td><td>'+(p.kind==='rent'?'Rent — '+esc(p.property_name||'')+', '+esc(p.space_name||''):'Sale — '+esc(p.sale_property_name||''))+'</td></tr><tr><td>Method</td><td>'+esc(p.method)+'</td></tr><tr><td>Status</td><td>'+(p.voided?chip('Cancelled'):chip('Paid'))+'</td></tr></table></div>';}
  else result='<div class="card verify-bad"><h3>&#10007; Not valid</h3><p>This receipt number and code do not match a real payment. It may be fake.</p></div>';}
 const body='<div class="verify-wrap"><h1>Verify a receipt</h1><p class="muted">Enter the receipt number and the verification code printed on it.</p><form method="get" class="rowform"><input name="receipt_no" placeholder="Receipt number e.g. RC-00001" value="'+esc(rn)+'"><input name="code" placeholder="Verification code" value="'+esc(code)+'"><button class="btn primary">Verify</button></form>'+result+'</div>';
 res.send(layout(req,'Verify a receipt',body));});
for(const key of['properties','spaces','tenants','customers','seekers','sales','tasks','expenses'])crud(key);
const CSS=`
:root{--blue:#2563eb;--blue-d:#1e40af;--bg:#eef2f7;--card:#fff;--line:#e3e8ef;--text:#0f172a;--muted:#64748b;--green:#16a34a;--green-bg:#dcfce7;--amber:#b45309;--amber-bg:#fef3c7;--red:#dc2626;--red-bg:#fee2e2;--gray-bg:#e2e8f0;--blue-bg:#dbeafe;--radius:14px;--shadow:0 1px 3px rgba(15,23,42,.06),0 8px 24px rgba(15,23,42,.05)}
*{box-sizing:border-box}body{margin:0;font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;background:var(--bg);color:var(--text);font-size:15px;line-height:1.55}
a{color:var(--blue);text-decoration:none}a:hover{text-decoration:underline}h1{font-size:1.55rem;margin:0;font-weight:700;letter-spacing:-.01em}h3{font-size:1.02rem;margin:.2rem 0;font-weight:700}h4{margin:.9rem 0 .4rem;font-weight:700}
.shell{display:flex;min-height:100vh}.sidebar{width:252px;background:linear-gradient(180deg,#0f172a,#1e293b);color:#cbd5e1;flex-shrink:0;padding:16px 12px;position:sticky;top:0;height:100vh;overflow-y:auto}
.brand{display:flex;align-items:center;gap:9px;color:#fff;font-weight:700;padding:6px 8px 16px;font-size:1.02rem}.brand img{height:32px;width:32px;object-fit:contain;border-radius:8px;background:#fff}
.sidebar nav{display:flex;flex-direction:column;gap:2px}.sidebar a,.sidebar .linklike{color:#cbd5e1;padding:9px 11px;border-radius:9px;font-size:.9rem;display:block;background:none;border:none;text-align:left;cursor:pointer;width:100%;font-family:inherit;transition:background .15s}
.sidebar a:hover,.sidebar .linklike:hover{background:rgba(255,255,255,.08);color:#fff;text-decoration:none}.sidebar a.on{background:var(--blue);color:#fff;box-shadow:0 4px 12px rgba(37,99,235,.4)}
.nav-group{color:#64748b;font-size:.68rem;text-transform:uppercase;letter-spacing:.08em;padding:15px 11px 5px;font-weight:700}.badge{background:var(--red);color:#fff;border-radius:10px;padding:0 7px;font-size:.72rem;margin-left:4px}.logout-form{margin-top:8px}
.main{flex:1;min-width:0;display:flex;flex-direction:column}.topbar{display:flex;align-items:center;gap:12px;background:rgba(255,255,255,.9);backdrop-filter:blur(8px);border-bottom:1px solid var(--line);padding:11px 22px;position:sticky;top:0;z-index:20}
.menu-btn{display:none;font-size:1.3rem;background:none;border:none;cursor:pointer}.topsearch{flex:1}.topsearch input{width:100%;max-width:560px;padding:10px 14px;border:1px solid var(--line);border-radius:10px;font-size:.9rem;background:#f8fafc}
.topname{color:var(--text);font-weight:600;text-align:right;line-height:1.2}.topname small{display:block;color:var(--muted);font-weight:400}.content{padding:22px;max-width:1280px;width:100%;margin:0 auto}
.page-head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:18px}.page-head>div{display:flex;gap:8px;flex-wrap:wrap}
.card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:18px;margin-bottom:16px;box-shadow:var(--shadow)}.card-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;gap:8px;flex-wrap:wrap}
.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:12px;margin-bottom:16px}.cards.mini{grid-template-columns:repeat(auto-fill,minmax(120px,1fr));margin-bottom:8px}
.stat{display:flex;flex-direction:column;gap:4px;padding:15px;margin:0;color:var(--text)}a.stat:hover{border-color:var(--blue);text-decoration:none;transform:translateY(-1px)}.stat-label{color:var(--muted);font-size:.78rem}.stat-value{font-size:1.4rem;font-weight:700}
.stat.warn{border-color:var(--amber);background:var(--amber-bg)}.stat.big .stat-value{color:var(--blue)}.money-cards .stat{border-left:4px solid var(--blue)}.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.table-wrap{overflow-x:auto}.table{width:100%;border-collapse:collapse;font-size:.9rem}.table th{text-align:left;color:var(--muted);font-weight:700;font-size:.72rem;text-transform:uppercase;letter-spacing:.04em;padding:9px 8px;border-bottom:2px solid var(--line)}
.table td{padding:9px 8px;border-bottom:1px solid var(--line);vertical-align:middle}.table tr:hover td{background:#f8fafc}.table .num{text-align:right;white-space:nowrap}
.chip{display:inline-block;padding:2px 10px;border-radius:20px;font-size:.76rem;font-weight:600;background:var(--gray-bg);color:var(--text);white-space:nowrap}.chip.green{background:var(--green-bg);color:var(--green)}.chip.amber{background:var(--amber-bg);color:var(--amber)}.chip.red{background:var(--red-bg);color:var(--red)}.chip.blue{background:var(--blue-bg);color:var(--blue-d)}.chip.gray{background:var(--gray-bg);color:var(--muted)}
.btn{display:inline-block;padding:8px 15px;border-radius:9px;border:1px solid var(--line);background:#fff;color:var(--text);font-size:.87rem;font-weight:600;cursor:pointer;font-family:inherit;line-height:1.3;transition:all .15s}.btn:hover{border-color:var(--blue);color:var(--blue);text-decoration:none}
.btn.primary{background:var(--blue);border-color:var(--blue);color:#fff;box-shadow:0 4px 12px rgba(37,99,235,.3)}.btn.primary:hover{background:var(--blue-d);color:#fff}.btn.danger{color:var(--red);border-color:#fca5a5}.btn.danger:hover{background:var(--red);color:#fff;border-color:var(--red)}
.btn.small{padding:5px 10px;font-size:.78rem}.btn.big{padding:12px 20px;font-size:1rem}.btn.full{width:100%;text-align:center}.inline{display:inline}.actions{white-space:nowrap}.actions .btn,.actions form{margin:1px}
.filterbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:14px}.filterbar input[type=search]{flex:1;min-width:180px;padding:10px 13px;border:1px solid var(--line);border-radius:9px}.filterbar select,.filterbar input[type=date]{padding:8px;border:1px solid var(--line);border-radius:9px;background:#fff}
.inline-label{display:flex;align-items:center;gap:6px;color:var(--muted);font-size:.84rem}.rowform{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:8px 0}.rowform input,.rowform select{padding:8px;border:1px solid var(--line);border-radius:9px}
.form-card{max-width:900px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:13px}.field{display:flex;flex-direction:column;gap:4px}.field.wide{grid-column:1/-1}.field label{font-size:.84rem;font-weight:600}
.field input,.field select,.field textarea{padding:10px 12px;border:1px solid var(--line);border-radius:9px;font-size:.92rem;font-family:inherit;background:#fff;width:100%}.field input:focus,.field select:focus,.field textarea:focus{outline:2px solid var(--blue);border-color:var(--blue)}
.req{color:var(--red)}.help{color:var(--muted);font-size:.76rem}.form-actions{display:flex;gap:10px;margin-top:16px}.form-actions.wide{grid-column:1/-1}
.check{display:flex;align-items:center;gap:8px;font-size:.9rem;font-weight:400!important;cursor:pointer}.check input{width:auto}.check-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:6px;margin-bottom:10px}.multi{width:100%;padding:6px;border:1px solid var(--line);border-radius:9px}
.dl{display:grid;grid-template-columns:170px 1fr;gap:7px 12px;margin:0}.dl dt{color:var(--muted);font-size:.84rem}.dl dd{margin:0}
.flash{background:var(--green-bg);color:var(--green);border:1px solid #bbf7d0;padding:12px 16px;border-radius:9px;margin-bottom:16px;font-weight:600}.flash-err{background:var(--red-bg);color:var(--red);border-color:#fecaca}
.muted{color:var(--muted)}.small-text{font-size:.8rem}.note{background:#f8fafc;border-left:3px solid var(--blue);padding:8px 12px;border-radius:6px}
.tabs{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px}.tab{padding:7px 14px;border-radius:20px;background:#fff;border:1px solid var(--line);color:var(--text);font-size:.84rem;font-weight:600}.tab.on{background:var(--blue);color:#fff;border-color:var(--blue)}.tab:hover{text-decoration:none;border-color:var(--blue)}
.pager{display:flex;gap:4px;margin-top:12px;flex-wrap:wrap}.pg{padding:5px 11px;border:1px solid var(--line);border-radius:7px;background:#fff;color:var(--text)}.pg.on{background:var(--blue);color:#fff;border-color:var(--blue)}
.notif-row{display:flex;justify-content:space-between;gap:10px;align-items:center;padding:10px 4px;border-bottom:1px solid var(--line)}.notif-row.unread{background:var(--blue-bg);border-radius:9px;padding:10px}.notif{padding:6px 0;border-bottom:1px solid var(--line);margin:0}.notif.unread{font-weight:600}.notif small,.notif-row small{display:block}
.bars{display:flex;gap:14px;align-items:flex-end;padding:10px 4px}.bar-col{display:flex;flex-direction:column;align-items:center;gap:6px;font-size:.76rem;color:var(--muted)}.bar-pair{display:flex;gap:3px;align-items:flex-end;height:124px}.bar{width:16px;border-radius:3px 3px 0 0}.bar.in{background:var(--blue)}.bar.out{background:#f59e0b}.dot{display:inline-block;width:10px;height:10px;border-radius:2px}.dot.in{background:var(--blue)}.dot.out{background:#f59e0b}
.gallery{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.gallery img{width:110px;height:85px;object-fit:cover;border-radius:9px;border:1px solid var(--line)}.plain-list{margin:0;padding-left:18px;font-size:.9rem}
.login-wrap{min-height:90vh;display:flex;align-items:center;justify-content:center;padding:20px}.login-card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:34px;width:100%;max-width:410px;box-shadow:0 20px 50px rgba(15,23,42,.12)}.login-brand{text-align:center;margin-bottom:20px}.login-brand img{height:54px;margin-bottom:8px}.login-brand h1{font-size:1.3rem}.login-brand p{color:var(--muted);font-size:.88rem;margin:.3rem 0 0}.login-card .field{margin-bottom:13px}
.plain{max-width:760px;margin:0 auto;padding:24px}.error-page{text-align:center;padding:60px 20px}.error-page h1{margin-bottom:10px}.error-code{display:inline-block;background:var(--red-bg);color:var(--red);font-weight:700;padding:4px 14px;border-radius:20px;margin-bottom:12px}
.scan-card{max-width:520px;margin:0 auto}.reader{width:100%;margin:12px 0;border-radius:12px;overflow:hidden}.scan-room{max-width:520px;margin:0 auto}.scan-room h1{font-size:1.7rem}.big-name{font-size:1.2rem;font-weight:700}.scan-actions{display:flex;flex-direction:column;gap:10px;margin:14px 0}
.print-body{background:#fff;padding:20px}.print-sheet{max-width:640px;margin:0 auto}.print-sheet h1{font-size:1.3rem}.receipt-head{display:flex;gap:14px;align-items:center;border-bottom:2px solid var(--text);padding-bottom:12px;margin-bottom:14px}.receipt-logo{height:56px}.big-amount{font-size:1.3rem}
.print-toolbar{display:flex;gap:14px;align-items:center;margin-bottom:16px;flex-wrap:wrap}.qr-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.qr-card{border:2px dashed #94a3b8;border-radius:10px;padding:14px;text-align:center;page-break-inside:avoid}.qr-company{font-size:.7rem;color:var(--muted);text-transform:uppercase;letter-spacing:.05em}.qr-property{font-weight:700;margin-top:4px}.qr-room{font-size:1.15rem;font-weight:800;margin:2px 0 8px}.qr-card img{width:100%;max-width:220px}.qr-hint{font-size:.74rem;color:var(--muted);margin-top:6px}
.toast-wrap{position:fixed;top:18px;right:18px;z-index:9999;display:flex;flex-direction:column;gap:10px;max-width:360px}
.toast{display:flex;align-items:flex-start;gap:11px;background:#fff;border-radius:12px;padding:13px 15px;box-shadow:0 10px 30px rgba(15,23,42,.18);border-left:4px solid var(--green);animation:slidein .25s ease}
.toast-err{border-left-color:var(--red)}.toast-icon{width:24px;height:24px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:700;color:#fff;background:var(--green);flex-shrink:0}.toast-err .toast-icon{background:var(--red)}
.toast-body{display:flex;flex-direction:column;gap:2px;font-size:.86rem}.toast-body strong{font-size:.9rem}.toast-err .toast-body strong{color:var(--red)}.toast-x{background:none;border:none;font-size:1.2rem;cursor:pointer;color:var(--muted);line-height:1;padding:0 2px}
@keyframes slidein{from{transform:translateX(40px);opacity:0}to{transform:translateX(0);opacity:1}}
.attn{border:2px solid var(--red);background:var(--red-bg);border-radius:14px;padding:14px 16px;margin-bottom:18px}
.attn-head{font-weight:800;color:var(--red);font-size:1rem;margin-bottom:10px}
.attn-item{background:#fff;border-radius:10px;padding:11px 13px;margin-bottom:9px;border-left:4px solid var(--red)}
.attn-good{border-left-color:var(--green)}.attn-msg{font-size:.92rem;margin-bottom:8px}.attn-actions{display:flex;gap:7px;flex-wrap:wrap;align-items:center}.attn-form{display:flex;gap:5px;align-items:center}.attn-form input{padding:6px 8px;border:1px solid var(--line);border-radius:7px;font-size:.8rem;width:130px}
.fired-page{max-width:560px;margin:40px auto;text-align:center}.fired-icon{font-size:3rem}.fired-page h1{margin:10px 0}.fired-page .card{text-align:left;margin-top:20px}
.verify-wrap{max-width:620px;margin:30px auto}.verify-ok{border-left:4px solid var(--green)}.verify-ok h3{color:var(--green)}.verify-bad{border-left:4px solid var(--red)}.verify-bad h3{color:var(--red)}
hr{border:none;border-top:1px solid var(--line);margin:14px 0}
@media(max-width:900px){.grid-2{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}.dl{grid-template-columns:130px 1fr}}
@media(max-width:768px){.sidebar{position:fixed;left:-262px;z-index:50;transition:left .2s;height:100vh}.sidebar.open{left:0;box-shadow:0 0 0 100vmax rgba(0,0,0,.4)}.menu-btn{display:block}.content{padding:14px}.topbar{padding:10px 12px}.topname small{display:none}.qr-grid{grid-template-columns:repeat(2,1fr)}.btn{padding:10px 14px}.btn.small{padding:7px 10px}.toast-wrap{left:12px;right:12px;max-width:none}}
@media print{.sidebar,.topbar,.no-print,.filterbar,.pager,.actions,.attn,.toast-wrap{display:none!important}.shell{display:block}.content{padding:0;max-width:none}.card{border:none;padding:0;margin:0 0 10px;box-shadow:none}body{background:#fff;font-size:12px}.qr-grid{gap:6px}.qr-card{border-color:#000}}
`;
const APPJS=`
const menuBtn=document.getElementById('menuBtn'),sidebar=document.getElementById('sidebar');
if(menuBtn&&sidebar){menuBtn.addEventListener('click',()=>sidebar.classList.toggle('open'));document.addEventListener('click',e=>{if(sidebar.classList.contains('open')&&!sidebar.contains(e.target)&&e.target!==menuBtn)sidebar.classList.remove('open');});}
document.querySelectorAll('form[data-confirm]').forEach(f=>f.addEventListener('submit',e=>{if(!confirm(f.dataset.confirm))e.preventDefault();}));
document.querySelectorAll('button[data-confirm]').forEach(b=>b.addEventListener('click',e=>{if(!confirm(b.dataset.confirm))e.preventDefault();}));
const tw=document.getElementById('toastWrap');if(tw){setTimeout(()=>{tw.style.transition='opacity .4s';tw.style.opacity='0';setTimeout(()=>tw.remove(),450);},5000);}
const kindSel=document.getElementById('payKind'),tenancyField=document.getElementById('tenancyField'),saleField=document.getElementById('saleField'),tenancySel=document.getElementById('tenancySel'),hint=document.getElementById('tenancyHint');
function syncKind(){if(!kindSel)return;const rent=kindSel.value==='rent';tenancyField.style.display=rent?'':'none';saleField.style.display=rent?'none':'';}
if(kindSel){kindSel.addEventListener('change',syncKind);syncKind();}
if(tenancySel&&hint){const load=async()=>{const id=tenancySel.value;hint.textContent='';if(!id)return;try{const r=await fetch('/api/tenancies/'+id+'/summary');if(!r.ok)return;const s=await r.json();const m=p=>'Rs. '+(p/100).toLocaleString('en-US');hint.textContent='Remaining amount: '+m(s.remaining)+' · Status: '+s.status+(s.nextDue?' · Due: '+s.nextDue:'')+(s.advance>0?' · Advance already paid: '+m(s.advance):'');}catch(e){}};tenancySel.addEventListener('change',load);if(tenancySel.value)load();}
const startBtn=document.getElementById('startScan');
if(startBtn&&window.Html5Qrcode){let scanner=null;startBtn.addEventListener('click',async()=>{startBtn.disabled=true;startBtn.textContent='Starting camera…';try{scanner=new Html5Qrcode('reader');await scanner.start({facingMode:'environment'},{fps:10,qrbox:240},text=>{let target=text.trim();const m=target.match(/\\/scan\\/([a-f0-9]+)/);if(m)target='/scan/'+m[1];else if(/^[a-f0-9]{20,}$/.test(target))target='/scan/'+target;else{alert('This QR code is not from this system.');scanner.stop();startBtn.disabled=false;startBtn.textContent='Start the camera';return;}scanner.stop().then(()=>{window.location.href=target;});},()=>{});startBtn.textContent='Camera is on — point it at the code';}catch(err){startBtn.disabled=false;startBtn.textContent='Start the camera';alert('The camera could not start. Use your phone\\u2019s normal camera app to scan the code, or paste the link below.');}});}
`;
app.get('/style.css',(req,res)=>{res.type('css').send(CSS);});
app.get('/app.js',(req,res)=>{res.type('js').send(APPJS);});
app.use((req,res)=>res.status(404).send(layout(req,'Not found',errBox('E-1005','We could not find that page. Check the address, or use the menu.'))));
app.use((e,req,res,next)=>{console.error('ERROR E-1000:',e);const msg=e.code==='LIMIT_FILE_SIZE'?'That file is too big. The limit is 10 MB.':'Something went wrong on our side. Please try again. If it keeps happening, tell your manager (error E-1000).';res.status(500).send(layout(req,'Something went wrong',errBox('E-1000',msg)));});
function selftest(){console.log('Running self-test…');let pass=0,fail=0;const ok=(n,c)=>{if(c){pass++;console.log('  PASS  '+n);}else{fail++;console.log('  FAIL  '+n);}};
 ok('money 25000 -> 2500000 paisa',paisa('25000')===2500000);
 ok('money 25,000.50 -> 2500050',paisa('25,000.50')===2500050);
 ok('addMonths rolls year',addMonths('2026-11',3)==='2027-02');
 ok('due day clamps to month end',dueDateFor('2026-02',31)==='2026-02-28');
 ok('status partly paid',recordStatus(2500000,2000000,'2099-01-05','2026-01-01')==='Partly Paid');
 ok('status late',recordStatus(2500000,0,'2020-01-05','2026-01-01')==='Late');
 ok('status paid',recordStatus(2500000,2500000,'2020-01-05','2026-01-01')==='Paid');
 const admin=db.prepare("SELECT * FROM users WHERE role='admin' LIMIT 1").get();
 ok('admin exists',!!admin);ok('admin full access',can(admin,'settings')&&can(admin,'payments.add'));
 const p=db.prepare("INSERT INTO properties(name,type,created_at) VALUES('__test','House',?)").run(nowISO()).lastInsertRowid;
 const s=db.prepare("INSERT INTO spaces(property_id,name,rent,due_day,status,created_at) VALUES(?,'__testroom',2500000,5,'Empty',?)").run(p,nowISO()).lastInsertRowid;
 const t=db.prepare("INSERT INTO tenants(name,phone,created_at) VALUES('__test','000',?)").run(nowISO()).lastInsertRowid;
 const ten=db.prepare("INSERT INTO tenancies(tenant_id,space_id,rent,due_day,move_in) VALUES(?,?,2500000,5,?)").run(t,s,monthKey()+'-01').lastInsertRowid;
 ensureRecords();let sum=tenancySummary(ten);ok('rent due created',sum.due===2500000);
 const pay=db.prepare("INSERT INTO payments(kind,tenancy_id,amount,paid_on,method,added_by,created_at) VALUES('rent',?,2000000,?,'Cash',?,?)").run(ten,todayISO(),admin.id,nowISO()).lastInsertRowid;
 db.prepare("UPDATE payments SET receipt_no=? WHERE id=?").run('RC-T'+pay,pay);reallocateTenancy(ten);sum=tenancySummary(ten);
 ok('partial remaining = 500000',sum.remaining===500000);ok('part-paid and late = Late',sum.status==='Late');
 const pp=db.prepare('SELECT * FROM payments WHERE id=?').get(pay);const vc=verifyCode(pp);ok('receipt code verifies',vc===verifyCode(pp)&&vc.length===16);ok('wrong code rejected',verifyCode({...pp,amount:pp.amount+1})!==vc);
 ok('audit chain intact',verifyAudit().ok===true);
 const emp=db.prepare("INSERT INTO users(role,name,email,password_hash,job_role,created_at) VALUES('employee','__testemp','__t@t.co',?,'Staff',?)").run(bcrypt.hashSync('x',10),nowISO()).lastInsertRowid;
 ok('employee no admin access',!can(db.prepare('SELECT * FROM users WHERE id=?').get(emp),'settings'));
 db.prepare('UPDATE users SET fired=1 WHERE id=?').run(emp);ok('fired employee blocked',!can(db.prepare('SELECT * FROM users WHERE id=?').get(emp),'properties.viewAssigned'));
 const perf=performance(emp);ok('performance returns score',typeof perf.score==='number'&&perf.score>=0&&perf.score<=100);
 db.prepare('DELETE FROM payments WHERE id=?').run(pay);db.prepare('DELETE FROM tenancies WHERE id=?').run(ten);db.prepare('DELETE FROM tenants WHERE id=?').run(t);db.prepare('DELETE FROM spaces WHERE id=?').run(s);db.prepare('DELETE FROM properties WHERE id=?').run(p);db.prepare('DELETE FROM users WHERE id=?').run(emp);
 console.log('\nSelf-test: '+pass+' passed, '+fail+' failed.');process.exit(fail?1:0);}
if(process.argv.includes('--selftest')){selftest();}
else{app.listen(PORT,()=>{console.log('Real Estate Management System is running → http://localhost:'+PORT);checkDue();setInterval(()=>{try{checkDue();}catch(e){console.error(e);}},6*3600*1000);});}
